import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems = {} }) {
  const itemId = item._id; 
const isPurchased = !!purchasedItems[itemId];
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        // Force the User ID to a string immediately
        const uid = String(decoded._id || decoded.id || decoded.userId);
        setCurrentUserId(uid);
        console.log("Logged in User ID:", uid);
      } catch (err) {
        console.error("Token decode failed", err);
      }
    }

    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => {
        setItems(data);
        console.log("Books fetched:", data);
      })
      .catch((err) => console.error("Fetch error", err))
      .finally(() => setLoading(false));
  }, []);

  // FORCE STRING COMPARISON FOR FILTERING
  const filteredItems = items.filter((item) => {
    if (!currentUserId) return true;
    
    // Some backends use item.userId, some use item.sellerId. 
    // Check which one your backend sends!
    const sellerId = String(item.userId || item.user || item.sellerId || "");
    
    return sellerId !== currentUserId; 
  });

  if (loading) return <h1>Loading...</h1>;

  return (
    <>
      <Navbar />
      <div className="Body" style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
        {filteredItems.length === 0 ? (
          <h1>No books for sale!</h1>
        ) : (
          filteredItems.map((item) => {
            // FORCE STRING ID for the cart check
            const itemId = String(item._id || item.id);
            const isPurchased = purchasedItems && !!purchasedItems[itemId];

            return (
              <Card key={itemId} {...item}>
                <button
                  onClick={() => !isPurchased && onBuy(item)}
                  disabled={isPurchased}
                  style={{
                    backgroundColor: isPurchased ? "#6c757d" : "#0d6efd", // Grey if purchased
                    color: "#fff",
                    borderRadius: "5px",
                    padding: "10px",
                    width: "140px",
                    border: "none",
                    // The "Unclickable" magic:
                    cursor: isPurchased ? "not-allowed" : "pointer",
                    pointerEvents: isPurchased ? "none" : "auto", 
                    opacity: isPurchased ? 0.6 : 1,
                  }}
                >
                  {isPurchased ? "Added to Cart" : "Add to Cart"}
                </button>
              </Card>
            );
          })
        )}
      </div>
      <Footer />
    </>
  );
}

export default Shop;
